package com.taylordproductivty.med_timing_tracker.data

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity(tableName = "dose_logs")
data class DoseLog(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    // Linking columns, no @ForeignKey -- matches this app's soft-relation convention.
    val profileId: Int,
    val medicationId: Int,
    val givenAtEpochMillis: Long,
    // Snapshot-copied from Medication.defaultDose at log time so later edits to a
    // medication's default dose don't silently rewrite past history.
    val doseAmount: String,
    val nextEligibleAtEpochMillis: Long? = null,
    // True if the user logged this dose despite the "too soon" warning dialog -- an
    // audit trail, not a block: two caregivers logging close together is exactly the
    // scenario this app exists to surface, not prevent outright.
    val wasOverrideWarningAcknowledged: Boolean = false,
    val createdAt: Long = System.currentTimeMillis(),
)
